mapper.select:
select pu.pup_id as pupId, p.PP_ID as ppId, p.pp_name as ppName, p.pp_code as ppCode, d.Pd_ID as pdId, d.PD_Code as pdCode, c1.C_Name as cName, u.u_mtel as uMtel, u.u_name as uName, u.U_ID as uId, d.PD_Name as pdName from SYS_User u left join SYS_Position_User_P pu on u.U_ID=pu.U_ID left join SYS_Position_P p on pu.PP_ID=p.PP_ID left join SYS_Department_P d on d.PD_ID=p.PD_ID left join Sys_Company c1 on c1.C_ID=u.C_ID where d.P_ID=#{pId} and p.PP_Status = '1' and d.PD_Status = '1' and d.Pd_Code in
#{pdCode}
order by d.PD_Sort, pu.pup_sort asc
